<?php
$regs=iterator_to_array(collection('registrations')->find([],['sort'=>['registered_at'=>-1],'limit'=>300]));
?>
<section class="panel table-panel full-panel"><div class="panel-heading split"><div><span class="eyebrow">ATTENDANCE OVERVIEW</span><h2>All registrations <span class="count"><?= count($regs) ?></span></h2><p>Every student sign-up, in one organised view.</p></div><a class="btn btn-primary" href="index.php?page=register">＋ New registration</a></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Event</th><th>Event date</th><th>Registered</th><th>Status</th></tr></thead><tbody><?php foreach($regs as $r): ?><tr><td><strong><?= h($r['student_name']??'') ?></strong><small><?= h($r['student_email']??'') ?></small></td><td><?= h($r['event_name']??'') ?></td><td><?= h($r['event_date']??'') ?></td><td><?= isset($r['registered_at'])?$r['registered_at']->toDateTime()->format('d M Y, H:i'):'—' ?></td><td><span class="status-tag">Confirmed</span></td></tr><?php endforeach; ?><?php if(!$regs): ?><tr><td colspan="5" class="empty">No registrations yet.</td></tr><?php endif; ?></tbody></table></div></section>
